before:
```typescript
interface Visit {
  place: string;
  note?: string;
}
const trip: Visit = { place: "Forest" };
```
The missing note is allowed. Reading trip.note produces undefined.

```typescript
interface Visit { place: string; note?: string }
function visitNote(visit: Visit): string {
  return visit.note ?? "No note";
}
console.log(visitNote({ place: "Forest" }));
console.log(visitNote({ place: "Forest", note: "" }));
```
The first call returns No note. The second returns an empty string: a present empty value is different from a missing property.

```typescript
interface Ticket { readonly title: string }
const ticket: Ticket = { title: "Museum" };
console.log(ticket.title);
// ticket.title = "Cinema"; // TypeScript would reject this assignment.
```

after:
The `??` operator chooses backup text when the value is null or undefined.
```typescript
interface Visit { place: string; note?: string; }
function visitNote(visit: Visit): string {
  return visit.note ?? "No note";
}
console.log(visitNote({ place: "Forest" }));
```
The output is No note.
